test('derives levels and reports only the first level increase', () {
  final relationship = NpcRelationshipState(
    npcId: 'npc-01',
    affinity: 2,
    seenDialogueIds: {'npc-01-greeting'},
    flags: {'greeted'},
  );

  final levelOne = relationship.applyAffinityDelta(1);
  final laterAffinity = levelOne.relationship.applyAffinityDelta(4);

  expect(levelOne.relationship.affinity, 3);
  expect(levelOne.relationship.level, 1);
  expect(levelOne.levelIncreased, isTrue);
  expect(levelOne.relationship.npcId, 'npc-01');
  expect(levelOne.relationship.seenDialogueIds, {'npc-01-greeting'});
  expect(levelOne.relationship.flags, {'greeted'});
  expect(laterAffinity.relationship.affinity, 7);
  expect(laterAffinity.relationship.level, 1);
  expect(laterAffinity.levelIncreased, isFalse);
});

test('signed affinity clamps at zero and relationship level recovers', () {
  final relationship = NpcRelationshipState(npcId: 'npc-01', affinity: 3);

  final lost = relationship.applyAffinityDelta(-1);
  final clamped = lost.relationship.applyAffinityDelta(-99);
  final recovered = clamped.relationship.applyAffinityDelta(3);

  expect(lost.relationship.affinity, 2);
  expect(lost.relationship.level, 0);
  expect(clamped.relationship.affinity, 0);
  expect(recovered.relationship.level, 1);
  expect(recovered.levelIncreased, isTrue);
});

test(
  'authored threshold controls level derivation and affinity updates',
  () {
    final relationship = NpcRelationshipState(
      npcId: 'npc-custom',
      affinity: 4,
      levelOneAffinity: 5,
    );

    final levelOne = relationship.applyAffinityDelta(
      1,
      levelOneAffinity: 5,
    );

    expect(relationship.level, 0);
    expect(levelOne.relationship.affinity, 5);
    expect(levelOne.relationship.level, 1);
    expect(levelOne.levelIncreased, isTrue);
  },
);

test('rejects persisted levels inconsistent with affinity', () {
  expect(
    () => NpcRelationshipState(npcId: 'npc-01', affinity: 3, level: 0),
    throwsArgumentError,
  );
  expect(
    () => NpcRelationshipState(npcId: 'npc-01', affinity: 0, level: 1),
    throwsArgumentError,
  );
  expect(
    NpcRelationshipState(npcId: 'npc-01', affinity: 3, level: 1).level,
    1,
  );
});

test('consumes inventory immutably without negative or zero counts', () {
  final inventory = InventoryState(
    itemCounts: {'moonflower': 2, 'other-item': 1},
  );

  final afterOne = inventory.consumeItem('moonflower');
  final afterLast = afterOne!.consumeItem('moonflower');

  expect(inventory.itemCounts, {'moonflower': 2, 'other-item': 1});
  expect(afterOne.itemCounts, {'moonflower': 1, 'other-item': 1});
  expect(afterLast!.itemCounts, {'other-item': 1});
  expect(afterLast.consumeItem('moonflower'), isNull);
  expect(inventory.consumeItem('missing-item'), isNull);
});

test('active selection clears only when its final item is consumed', () {
  final inventory = InventoryState(
    itemCounts: {'moonflower': 2, 'river_trout': 1},
  );

  expect(inventory.activateItem('missing'), isNull);
  final active = inventory.activateItem('moonflower')!;
  final afterOne = active.consumeItem('moonflower')!;
  final afterLast = afterOne.consumeItem('moonflower')!;

  expect(active.activeItemId, 'moonflower');
  expect(afterOne.activeItemId, 'moonflower');
  expect(afterLast.activeItemId, isNull);
  expect(afterLast.itemCounts, {'river_trout': 1});
});
